import React, { useEffect, useState } from 'react';
import { Card, CardContent, Grid, Typography } from '@mui/material';

function DashboardPage() {
  const [stats, setStats] = useState(null);

  useEffect(() => {
    fetch('/api/dashboard-stats')
      .then((res) => res.json())
      .then(setStats);
  }, []);

  return (
    <div>
      <Typography variant="h4" gutterBottom>
        Dashboard
      </Typography>
      <Grid container spacing={2}>
        {stats ? (
          [
            { title: 'Total Executions', value: stats.total_executions },
            { title: 'Pass Rate', value: `${stats.pass_rate}%` },
            { title: 'Fail Rate', value: `${stats.fail_rate}%` },
            { title: 'Top Flaky Tests', value: stats.top_flaky_tests.join(', ') },
          ].map((card) => (
            <Grid item xs={12} md={3} key={card.title}>
              <Card>
                <CardContent>
                  <Typography variant="h6">{card.title}</Typography>
                  <Typography>{card.value}</Typography>
                </CardContent>
              </Card>
            </Grid>
          ))
        ) : (
          <Typography>Loading...</Typography>
        )}
      </Grid>
    </div>
  );
}

export default DashboardPage;
